// Remove matching rows or columns of tiles, then let the remaining tiles fall down.
// match-grid: original MIT-licensed native educational port.
// Generated by tools/ports/generate.py; edit the specification to preserve parity.
// Input: [width,height,minimum_run,...tiles]
// Output: [matched_count,...collapsed_tiles]
// Tile -1 is empty. Detect horizontal/vertical matches, merge intersections, then apply column
// gravity. No random refill or cascade.
// Precondition: finite, correctly shaped data; integer indices/counts/IDs.
// See ../PORTS.md for examples, limits, and the shared test fixtures.

#include "mechanic.h"
#include <assert.h>
#include <math.h>
// Count how many numbers are in this list.
static inline double port_length(const PortVector *a) { return (double)a->count; }
// Check that a position is a whole number inside the list before using it.
static inline size_t port_index(const PortVector *a, double i) { assert(isfinite(i) && i>=0 && i<(double)a->count && floor(i)==i); return (size_t)i; }
// Read one number at a zero-based position; stop if that position does not exist.
static inline double port_get(const PortVector *a, double i) { return a->values[port_index(a,i)]; }
// Replace a number at an existing position in the list.
static inline void port_put(PortVector *a, double i, double v) { a->values[port_index(a,i)] = v; }
// Add one number to the end of the list.
static inline void port_push(PortVector *a, double v) { assert(a->count<PORT_CAPACITY); a->values[a->count++]=v; }

// 1. Find long enough runs of identical nonempty tiles.
// 2. Mark each matching tile once, even where a row and column cross.
// 3. Remove all marked tiles together.
// 4. Slide surviving tiles to the bottom of each column without changing their order.
PortVector game_match_grid_compute(PortVector data) {
    double w = 0;
    double h = 0;
    double minimum_run = 0;
    PortVector matched = {0};
    double i = 0;
    double axis = 0;
    double count = 0;
    PortVector grid = {0};
    double x = 0;
    PortVector result = {0};
    double lines = 0;
    double span = 0;
    double line = 0;
    double bottom = 0;
    double y = 0;
    double start = 0;
    double cell = 0;
    double stride = 0;
    double tile = 0;
    double end_index = 0;
    double j = 0;
    w = port_get(&data, 0.0);
    h = port_get(&data, 1.0);
    minimum_run = port_get(&data, 2.0);
    if (((w < 1.0) || (h < 1.0) || (minimum_run < 2.0) || (port_length(&data) != (3.0 + (w * h))))) {
        return (PortVector){.values={-(1.0)}, .count=1};
    }
    matched = (PortVector){.values={0}, .count=0};
    i = 0.0;
    while ((i < (w * h))) {
        port_push(&matched, 0.0);
        i += 1.0;
    }
    axis = 0.0;
    while ((axis < 2.0)) {
        lines = h;
        span = w;
        if ((axis == 1.0)) {
            lines = w;
            span = h;
        }
        line = 0.0;
        while ((line < lines)) {
            start = 0.0;
            while ((start < span)) {
                cell = ((line * w) + start);
                stride = 1.0;
                if ((axis == 1.0)) {
                    cell = ((start * w) + line);
                    stride = w;
                }
                tile = port_get(&data, (3.0 + cell));
                end_index = (start + 1.0);
                while (((end_index < span) && (port_get(&data, ((3.0 + cell) + ((end_index - start) * stride))) == tile))) {
                    end_index += 1.0;
                }
                if (((tile != -(1.0)) && ((end_index - start) >= minimum_run))) {
                    j = start;
                    while ((j < end_index)) {
                        port_put(&matched, (cell + ((j - start) * stride)), 1.0);
                        j += 1.0;
                    }
                }
                start = end_index;
            }
            line += 1.0;
        }
        axis += 1.0;
    }
    count = 0.0;
    grid = (PortVector){.values={0}, .count=0};
    i = 0.0;
    while ((i < (w * h))) {
        count += port_get(&matched, i);
        port_push(&grid, -(1.0));
        i += 1.0;
    }
    x = 0.0;
    while ((x < w)) {
        bottom = (h - 1.0);
        y = (h - 1.0);
        while ((y >= 0.0)) {
            cell = ((y * w) + x);
            if (((port_get(&matched, cell) == 0.0) && (port_get(&data, (3.0 + cell)) != -(1.0)))) {
                port_put(&grid, ((bottom * w) + x), port_get(&data, (3.0 + cell)));
                bottom -= 1.0;
            }
            y -= 1.0;
        }
        x += 1.0;
    }
    result = (PortVector){.values={count}, .count=1};
    i = 0.0;
    while ((i < port_length(&grid))) {
        port_push(&result, port_get(&grid, i));
        i += 1.0;
    }
    return result;
}
